+		size_t words = payload_size / sizeof(u32);
 		u32 *dst = dev->codebuf.vaddr;
 		int i;
 
+		if (payload_size % sizeof(u32))
+			return -EINVAL;
+
 		/* Firmware in native order, reorder while copying */
