+#define JPEG_V420_REG_WE_BSIZE_1	0x0ec
+#define JPEG_V420_REG_WE_BSIZE_2	0x0f0
+#define JPEG_V420_REG_WE_STRIDE_0	0x0f4
+#define JPEG_V420_REG_WE_STRIDE_1	0x0f8
