+}
+
+/*
+ * Called immediately before sched_change_begin(). The caller must pass
+ * DEQUEUE_NOCLOCK so the rq clock is updated only once.
+ */
+void scx_prepare_task_sched_change(struct task_struct *p, struct scx_sched *sch)
+{
